tensor_helper:
static void fast_tensor_transform(GFq_t *out,const GFq_t *t,
 const GFq_t *a,const GFq_t *b,const GFq_t *c,int n,int m){
 GFq_t t1[n*m*n],t2[m*m*n];
 for(int x=0;x<n;x++)for(int k=0;k<m;k++)for(int y=0;y<n;y++)
  t1[(x*m+k)*n+y]=fast_dot(t+(x*n+y)*n,c+k*n,n);
 for(int j=0;j<m;j++)for(int k=0;k<m;k++)for(int x=0;x<n;x++)
  t2[(j*m+k)*n+x]=fast_dot(t1+(x*m+k)*n,b+j*n,n);
 for(int i=0;i<m;i++)for(int j=0;j<m;j++)for(int k=0;k<m;k++)
  out[(i*m+j)*m+k]=fast_dot(t2+(j*m+k)*n,a+i*n,n);
}
